import { Composio } from "@composio/core";
import * as fs from "fs";
import * as path from "path";

interface TriggerStatus {
  userId: string;
  triggerTypes: any[];
  createdTrigger: {
    id: string;
    type: string;
    status: string;
    createdAt: string;
  } | null;
  disabledTrigger: {
    id: string;
    status: string;
    disabledAt: string;
  } | null;
  activeTriggers: any[];
  verification: {
    triggerId: string;
    isActive: boolean;
    message: string;
  };
}

async function main() {
  console.log("Starting trigger lifecycle management...");
  console.log("=".repeat(50));

  const userId = "zealt-user01";
  const outputPath = "/home/user/trigger_status.json";

  // Initialize Composio client
  const client = new Composio({
    apiKey: process.env.COMPOSIO_API_KEY || "",
  });

  console.log(`Creating session for user: ${userId}`);
  const session = client.sessions.create(userId);

  const triggerStatus: TriggerStatus = {
    userId,
    triggerTypes: [],
    createdTrigger: null,
    disabledTrigger: null,
    activeTriggers: [],
    verification: {
      triggerId: "",
      isActive: false,
      message: "",
    },
  };

  try {
    // Step 1: List available trigger types for GitHub toolkit
    console.log("\nStep 1: Listing available trigger types for GitHub toolkit...");
    const triggerTypes = await session.triggers.list_types("github");
    console.log(`Found ${triggerTypes.length} trigger types:`);

    triggerTypes.forEach((type: any, index: number) => {
      console.log(`  ${index + 1}. ${type.name || type.slug || type.id} - ${type.description || "No description"}`);
    });

    triggerStatus.triggerTypes = triggerTypes;

    // Find GITHUB_ISSUE_EVENT or similar trigger
    const githubIssueTrigger = triggerTypes.find(
      (type: any) =>
        type.slug?.toLowerCase().includes("github_issue") ||
        type.name?.toLowerCase().includes("github_issue") ||
        type.slug?.toLowerCase().includes("issue_event") ||
        type.name?.toLowerCase().includes("issue_event")
    );

    // Fallback to first available trigger if GITHUB_ISSUE_EVENT is not found
    const triggerToCreate = githubIssueTrigger || triggerTypes[0];

    if (!triggerToCreate) {
      throw new Error("No trigger types available for GitHub toolkit");
    }

    const triggerTypeSlug = triggerToCreate.slug || triggerToCreate.id;
    console.log(`\nStep 2: Creating trigger for type: ${triggerTypeSlug}`);

    // Step 2: Create an active trigger
    const createdTrigger = await session.triggers.create(triggerTypeSlug);
    console.log(`Trigger created successfully!`);
    console.log(`  Trigger ID: ${createdTrigger.id}`);
    console.log(`  Status: ${createdTrigger.status || "active"}`);

    triggerStatus.createdTrigger = {
      id: createdTrigger.id,
      type: triggerTypeSlug,
      status: createdTrigger.status || "active",
      createdAt: new Date().toISOString(),
    };

    // Step 3: Disable the newly created trigger
    console.log(`\nStep 3: Disabling trigger ${createdTrigger.id}...`);

    // Try different methods to disable the trigger
    let disableResult;
    try {
      disableResult = await session.triggers.disable(createdTrigger.id);
    } catch (error) {
      // Try alternative method if disable doesn't exist
      console.log("Trying alternative disable method...");
      disableResult = await session.triggers.update(createdTrigger.id, { active: false });
    }

    console.log(`Trigger disabled successfully!`);
    console.log(`  Result: ${JSON.stringify(disableResult)}`);

    triggerStatus.disabledTrigger = {
      id: createdTrigger.id,
      status: "disabled",
      disabledAt: new Date().toISOString(),
    };

    // Step 4: List active triggers and verify
    console.log(`\nStep 4: Listing active triggers for user ${userId}...`);
    const activeTriggers = await session.triggers.list({ active: true });
    console.log(`Found ${activeTriggers.length} active triggers:`);

    activeTriggers.forEach((trigger: any, index: number) => {
      console.log(`  ${index + 1}. ID: ${trigger.id} - Type: ${trigger.type || trigger.trigger_type}`);
    });

    triggerStatus.activeTriggers = activeTriggers;

    // Verify that the trigger is no longer active
    const isStillActive = activeTriggers.some(
      (trigger: any) => trigger.id === createdTrigger.id
    );

    triggerStatus.verification = {
      triggerId: createdTrigger.id,
      isActive: isStillActive,
      message: isStillActive
        ? "ERROR: Trigger is still active (should be disabled)"
        : "SUCCESS: Trigger has been successfully disabled and is no longer active",
    };

    console.log(`\nStep 5: Verification:`);
    console.log(`  Trigger ID: ${createdTrigger.id}`);
    console.log(`  Is Active: ${isStillActive}`);
    console.log(`  Message: ${triggerStatus.verification.message}`);

  } catch (error) {
    console.error("\nError during trigger lifecycle management:", error);
    triggerStatus.verification = {
      triggerId: triggerStatus.createdTrigger?.id || "",
      isActive: false,
      message: `Failed: ${error instanceof Error ? error.message : String(error)}`,
    };
  }

  // Step 5: Save trigger status to JSON file
  console.log(`\nStep 6: Saving trigger status to ${outputPath}...`);
  fs.writeFileSync(outputPath, JSON.stringify(triggerStatus, null, 2));
  console.log("Trigger status saved successfully!");

  console.log("\n" + "=".repeat(50));
  console.log("Trigger lifecycle management completed!");
  console.log("=".repeat(50));
}

// Run the main function
main().catch((error) => {
  console.error("Fatal error:", error);
  process.exit(1);
});

