import { Composio } from "@composio/core";
import * as fs from "fs";
import * as path from "path";

interface TriggerStatus {
  userId: string;
  triggerTypes: any[];
  createdTrigger: {
    triggerId: string;
    type: string;
    status: string;
    createdAt: string;
  } | null;
  disabledTrigger: {
    triggerId: string;
    status: string;
    disabledAt: string;
  } | null;
  activeTriggers: any[];
  verification: {
    triggerId: string;
    isActive: boolean;
    message: string;
  };
}

async function main() {
  console.log("Starting trigger lifecycle management...");
  console.log("=".repeat(50));

  const userId = "zealt-user01";
  const outputPath = "/home/user/trigger_status.json";

  // Initialize Composio client
  const composio = new Composio({
    apiKey: process.env.COMPOSIO_API_KEY || "",
  });

  const triggerStatus: TriggerStatus = {
    userId,
    triggerTypes: [],
    createdTrigger: null,
    disabledTrigger: null,
    activeTriggers: [],
    verification: {
      triggerId: "",
      isActive: false,
      message: "",
    },
  };

  try {
    // Step 1: List available trigger types for GitHub toolkit
    console.log("\nStep 1: Listing available trigger types for GitHub toolkit...");
    const triggerTypesResponse = await composio.triggers.listTypes({ toolkits: ["github"] });
    const triggerTypes = triggerTypesResponse.items;
    console.log(`Found ${triggerTypes.length} trigger types:`);

    triggerTypes.forEach((type: any, index: number) => {
      console.log(`  ${index + 1}. ${type.name || type.slug} - ${type.description || "No description"}`);
    });

    triggerStatus.triggerTypes = triggerTypes;

    // Find a trigger that doesn't require complex configuration
    // Try "Follower Changes" or other simple triggers first
    const simpleTrigger = triggerTypes.find(
      (type: any) =>
        type.slug?.toLowerCase().includes("follower") ||
        type.name?.toLowerCase().includes("follower")
    );

    // Fallback to "New Issue Created" which requires owner and repo
    const triggerToCreate = simpleTrigger || triggerTypes.find(
      (type: any) =>
        type.slug?.toLowerCase().includes("new_issue_created") ||
        type.name?.toLowerCase().includes("new issue created")
    );

    if (!triggerToCreate) {
      throw new Error("No suitable trigger types available for GitHub toolkit");
    }

    const triggerTypeSlug = triggerToCreate.slug;
    console.log(`\nStep 2: Creating trigger for type: ${triggerTypeSlug}`);

    // Step 2: Create an active trigger with configuration
    const triggerConfig: any = {};

    // Add required configuration if needed
    if (triggerTypeSlug.includes("ISSUE") || triggerTypeSlug.includes("issue")) {
      // For issue-related triggers, we need owner and repo
      // Use a public repository as example
      triggerConfig.owner = "octocat";
      triggerConfig.repo = "Hello-World";
    }

    const createdTrigger = await composio.triggers.create(userId, triggerTypeSlug, triggerConfig);
    console.log(`Trigger created successfully!`);
    console.log(`  Trigger ID: ${createdTrigger.triggerId}`);
    console.log(`  Status: active`);

    triggerStatus.createdTrigger = {
      triggerId: createdTrigger.triggerId,
      type: triggerTypeSlug,
      status: "active",
      createdAt: new Date().toISOString(),
    };

    // Step 3: Disable the newly created trigger
    console.log(`\nStep 3: Disabling trigger ${createdTrigger.triggerId}...`);
    const disableResult = await composio.triggers.disable(createdTrigger.triggerId);
    console.log(`Trigger disabled successfully!`);
    console.log(`  Result: ${JSON.stringify(disableResult)}`);

    triggerStatus.disabledTrigger = {
      triggerId: createdTrigger.triggerId,
      status: disableResult.status || "disabled",
      disabledAt: new Date().toISOString(),
    };

    // Step 4: List active triggers and verify
    console.log(`\nStep 4: Listing active triggers for user ${userId}...`);
    const activeTriggersResponse = await composio.triggers.listActive({ triggerIds: [createdTrigger.triggerId] });
    const activeTriggers = activeTriggersResponse.items;
    console.log(`Found ${activeTriggers.length} active triggers:`);

    activeTriggers.forEach((trigger: any, index: number) => {
      console.log(`  ${index + 1}. ID: ${trigger.id} - Type: ${trigger.triggerName}`);
    });

    triggerStatus.activeTriggers = activeTriggers;

    // Verify that the trigger is no longer active
    const isStillActive = activeTriggers.some(
      (trigger: any) => trigger.id === createdTrigger.triggerId
    );

    triggerStatus.verification = {
      triggerId: createdTrigger.triggerId,
      isActive: isStillActive,
      message: isStillActive
        ? "ERROR: Trigger is still active (should be disabled)"
        : "SUCCESS: Trigger has been successfully disabled and is no longer active",
    };

    console.log(`\nStep 5: Verification:`);
    console.log(`  Trigger ID: ${createdTrigger.triggerId}`);
    console.log(`  Is Active: ${isStillActive}`);
    console.log(`  Message: ${triggerStatus.verification.message}`);

  } catch (error) {
    console.error("\nError during trigger lifecycle management:", error);
    triggerStatus.verification = {
      triggerId: triggerStatus.createdTrigger?.triggerId || "",
      isActive: false,
      message: `Failed: ${error instanceof Error ? error.message : String(error)}`,
    };
  }

  // Step 5: Save trigger status to JSON file
  console.log(`\nStep 6: Saving trigger status to ${outputPath}...`);
  fs.writeFileSync(outputPath, JSON.stringify(triggerStatus, null, 2));
  console.log("Trigger status saved successfully!");

  console.log("\n" + "=".repeat(50));
  console.log("Trigger lifecycle management completed!");
  console.log("=".repeat(50));
}

// Run the main function
main().catch((error) => {
  console.error("Fatal error:", error);
  process.exit(1);
});

